  CONSTRAINT `fk_topology_edges_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_topology_edges_source` FOREIGN KEY (`source_device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_topology_edges_target` FOREIGN KEY (`target_device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `topology_icons` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `filename` varchar(255) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `topology_labels` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `project_id` int(10) unsigned NOT NULL DEFAULT 1,
  `text` varchar(512) NOT NULL DEFAULT '',
  `x` double NOT NULL DEFAULT 0,
  `y` double NOT NULL DEFAULT 0,
  `font_size` int(10) unsigned NOT NULL DEFAULT 14,
  `color` varchar(32) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `topology_id` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_topology_labels_project` (`project_id`),
  KEY `idx_topology_labels_topology` (`topology_id`),
  CONSTRAINT `fk_topology_labels_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `topology_layout` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `project_id` int(10) unsigned NOT NULL DEFAULT 1,
  `device_id` int(10) unsigned NOT NULL,
  `x` double NOT NULL DEFAULT 0,
  `y` double NOT NULL DEFAULT 0,
  `width` double NOT NULL DEFAULT 120,
  `height` double NOT NULL DEFAULT 80,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_topology_layout_device` (`device_id`),
  KEY `idx_topology_layout_project` (`project_id`),
  CONSTRAINT `fk_topology_layout_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_topology_layout_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `topology_node_interfaces` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `project_id` int(10) unsigned NOT NULL DEFAULT 1,
  `device_id` int(10) unsigned NOT NULL,
  `parent_id` int(10) unsigned DEFAULT NULL,
  `name` varchar(128) NOT NULL,
  `vlan_id` int(11) DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `speed` varchar(32) DEFAULT NULL,
  `cable_type` varchar(64) DEFAULT NULL,
  `status` varchar(10) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_topology_node_interfaces_device` (`device_id`),
  KEY `idx_topology_node_interfaces_project` (`project_id`),
  KEY `idx_topology_node_interfaces_parent` (`parent_id`),
  CONSTRAINT `fk_topology_node_interfaces_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_topology_node_interfaces_parent` FOREIGN KEY (`parent_id`) REFERENCES `topology_node_interfaces` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_topology_node_interfaces_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `topology_nodes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `project_id` int(10) unsigned NOT NULL DEFAULT 1,
  `device_id` int(10) unsigned DEFAULT NULL,
  `label` varchar(255) DEFAULT NULL,
  `type` varchar(64) DEFAULT NULL,
  `icon_color` varchar(16) DEFAULT NULL,
  `text_color` varchar(16) DEFAULT NULL,
  `x` double NOT NULL DEFAULT 0,
  `y` double NOT NULL DEFAULT 0,
  `width` double NOT NULL DEFAULT 120,
  `height` double NOT NULL DEFAULT 80,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `topology_id` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_topology_nodes_device` (`device_id`),
  KEY `idx_topology_nodes_project` (`project_id`),
  KEY `idx_topology_nodes_topology` (`topology_id`),
  CONSTRAINT `fk_topology_nodes_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_topology_nodes_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `topology_shapes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `project_id` int(10) unsigned NOT NULL,
  `shape_type` varchar(20) NOT NULL DEFAULT 'rect',
  `x` float NOT NULL DEFAULT 0,
  `y` float NOT NULL DEFAULT 0,
  `width` float NOT NULL DEFAULT 160,
  `height` float NOT NULL DEFAULT 100,
  `fill_color` varchar(50) NOT NULL DEFAULT '#3b82f620',
  `border_color` varchar(50) NOT NULL DEFAULT '#3b82f6',
  `label` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `topology_id` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_topology_shapes_project` (`project_id`),
  KEY `idx_topology_shapes_topology` (`topology_id`),
  CONSTRAINT `fk_topology_shapes_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `topology_zones` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `project_id` int(10) unsigned NOT NULL DEFAULT 1,
  `name` varchar(255) NOT NULL,
  `border_style` enum('solid','dotted') NOT NULL DEFAULT 'solid',
  `color` varchar(32) NOT NULL DEFAULT 'blue',
  `vlan_id` int(10) unsigned DEFAULT NULL,
  `x` double NOT NULL DEFAULT 0,
  `y` double NOT NULL DEFAULT 0,
  `width` double NOT NULL DEFAULT 300,
  `height` double NOT NULL DEFAULT 200,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `topology_id` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_topology_zones_project` (`project_id`),
  KEY `fk_topology_zones_vlan` (`vlan_id`),
  KEY `idx_topology_zones_topology` (`topology_id`),
  CONSTRAINT `fk_topology_zones_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_topology_zones_vlan` FOREIGN KEY (`vlan_id`) REFERENCES `project_vlans` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `user_catalog_entries` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `name` varchar(255) NOT NULL,
  `render_type` varchar(50) NOT NULL DEFAULT 'other',
  `u_size` int(10) unsigned NOT NULL DEFAULT 1,
  `color` varchar(20) DEFAULT NULL,
  `half_width` tinyint(1) NOT NULL DEFAULT 0,
  `half_depth` tinyint(1) NOT NULL DEFAULT 0,
  `mounted_face` enum('front','rear','both') NOT NULL DEFAULT 'front',
  `outlet_groups` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`outlet_groups`)),
  `input_voltage` varchar(20) DEFAULT NULL,
  `input_plug_type` varchar(50) DEFAULT NULL,
  `capacity_va` smallint(5) unsigned DEFAULT NULL,
  `capacity_w` smallint(5) unsigned DEFAULT NULL,
  `capacity_value` smallint(5) unsigned DEFAULT NULL,
  `capacity_unit` varchar(10) DEFAULT NULL,
  `port_count` smallint(5) unsigned DEFAULT NULL,
  `bay_count` smallint(5) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `runtime_curve` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`runtime_curve`)),
  `ebm_runtime_curve` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`ebm_runtime_curve`)),
  PRIMARY KEY (`id`),
  KEY `idx_user_catalog_entries_user` (`user_id`),
  CONSTRAINT `fk_user_catalog_entries_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(64) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `must_change_password` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



